"""Recorre recursivamente todos los hijos del contenedor (flexContainer)
y recolecta los custom.item en un JSON único. Además, si el componente
es un Flex Repeater (tiene props.instances), toma los items de sus instancias.
"""

def _append_item(candidate, out_list):
	"""Agrega al arreglo de salida un item con las claves esperadas, si existe."""
	if not candidate:
		return
	try:
		out_list.append({
			"papoItemID": candidate.get("papoItemID"),
			"registerTypeID": candidate.get("registerTypeID"),
			"answer": candidate.get("answer")
		})
	except Exception:
		# Silencioso: si el objeto no es mapeable, lo ignoramos
		pass


def _gather_from_instances(component):
	"""
	Intenta extraer items desde props.instances (Flex Repeater).
	Busca en:
	  - instancia['item']
	  - instancia['viewParams']['item']
	También soporta que 'item' sea una lista de ítems.
	"""
	items = []
	try:
		if hasattr(component, "props") and hasattr(component.props, "instances"):
			for inst in component.props.instances:
				# inst es un dict-like
				candidate = None
				# item directo en la instancia
				if hasattr(inst, "get"):
					candidate = inst.get("item", None)
					# o dentro de viewParams
					if candidate is None:
						vp = inst.get("viewParams", None)
						if hasattr(vp, "get"):
							candidate = vp.get("item", None)

				# 'item' puede ser un solo dict o una lista de dicts
				if candidate is not None:
					if isinstance(candidate, (list, tuple)):
						for it in candidate:
							_append_item(it, items)
					else:
						_append_item(candidate, items)
	except Exception:
		# Si algo falla, no rompemos el flujo
		pass

	return items


def gather_items(component):
	items = []

	# 1) Si este componente tiene custom.item, lo guardamos
	try:
		if hasattr(component, "custom") and hasattr(component.custom, "item"):
			_append_item(component.custom.item, items)
	except Exception:
		pass

	# 2) Si es un Flex Repeater (o similar) con props.instances, recolectamos desde las instancias
	#    y NO descendemos a sus hijos para evitar duplicados.
	if hasattr(component, "props") and hasattr(component.props, "instances"):
		items.extend(_gather_from_instances(component))
		return items  # Importante: no recursar hijos del repeater para no duplicar

	# 3) Recorremos hijos recursivamente
	try:
		for child in component.getChildren():
			items.extend(gather_items(child))
	except Exception:
		pass

	return items


# --- Ejecución principal ---
all_items = gather_items(flexContainer)  # empezamos desde el contenedor actual (p. ej., FlexContainer4)

# Agregar observaciones como un item extra (NO TOCAR)
insight_text = getattr(self.view.custom, "insights", None)
registerType = getattr(self.view.custom, "registerTypeID", None)
user = getattr(self.view.custom, "user", None)
hour = system.date.now()
if insight_text is not None:
	all_items.append({
		"user": user,
		"timestamp": hour,
		"insights": insight_text,   # 👈 insights como parte de "answer"
		"registerTypeID": registerType
	})

return {"items": all_items}
